#include "fedspatial/gpu_context.hpp"
#include <algorithm>
#include <cmath>
#include <cstring>
#include <filesystem>
#include <fstream>
#include <iostream>
using namespace fedspatial; namespace fs=std::filesystem;
static Matrix load(const fs::path&p){std::ifstream f(p);int r,c;if(!(f>>r>>c))throw std::runtime_error("missing "+p.string());Matrix x(r,c);for(double&v:x.a)f>>v;return x;}
static WorkerInput worker(int n){auto a=load("sync_gpu/tests/fixtures/figure1_reference/worker_0.txt");Matrix s(n,2),z(n,1),x(n,5);for(int i=0;i<n;++i){s(i,0)=a(i,0);s(i,1)=a(i,1);z(i,0)=a(i,2);for(int j=0;j<5;++j)x(i,j)=a(i,j+3);}return{s,z,x};}
static Matrix scaled(Matrix x,double s){for(double&v:x.a)v*=s;return x;} static double tr(const Matrix& x){double v=0.;for(int i=0;i<x.rows;++i)v+=x(i,i);return v;} static double inner(const Matrix& x,const Matrix& y){double v=0.;for(int i=0;i<x.rows*x.cols;++i)v+=x.a[i]*y.a[i];return v;}
static bool run(int n){const fs::path root="sync_gpu/tests/fixtures/figure1_reference";auto k=load(root/"knots.txt");GlobalParameters p{load(root/"p_initial_gamma_new.txt"),load(root/"p_initial_global_mu.txt"),load(root/"p_initial_global_sigma.txt"),.25,1.,.11};auto w=worker(n);GpuContext c(0);const auto h0=c.raw_h2d_bytes(),d0=c.result_d2h_bytes();auto a=compute_device_delta_theta_delta_hessian_reduction_streamed(c,w,k,p);const auto h1=c.raw_h2d_bytes(),d1=c.result_d2h_bytes();auto b=compute_device_delta_theta_delta_hessian_reduction_streamed(c,w,k,p);const auto oracle=compute_delta_theta_local_legacy_oracle(c,w,k,p,make_p_global_derivative_workspace(c,k,p));GpuContext dc(0);const auto s=build_device_mu_sigma_local(dc,w,k,p);const auto f=build_device_delta_theta_workspace(dc,s);const auto dense=download_device_delta_theta_workspace_for_test(dc,f);const auto local=download_device_mu_sigma_local(dc,s);const Matrix A=scaled(subtract(local.M,identity(n)),1./p.delta);const double twa=tr(matmul(dense.W,A)),twawa=tr(matmul(matmul(matmul(dense.W,A),dense.W),A)),qwaw=inner(dense.r,matmul(matmul(matmul(dense.W,A),dense.W),dense.r)),twawawq=tr(matmul(matmul(matmul(matmul(matmul(dense.W,A),dense.W),A),dense.W),dense.Q));const double terms=std::max({std::abs(a.trace_wa-twa),std::abs(a.trace_wawa-twawa),std::abs(a.quadratic_waw-qwaw),std::abs(a.trace_wawawq-twawawq)}),e=std::abs(a.delta_hessian-oracle.hessian[0]),rr=e/std::max({1.,std::abs(a.delta_hessian),std::abs(oracle.hessian[0])});const bool repeat=std::memcmp(&a,&b,sizeof(a))==0,stationary=c.raw_h2d_bytes()==h1;std::cout<<"STREAM_DELTA_HESSIAN_N="<<n<<" PYTHON_AUTOGRAD_DD_ABS="<<e<<" MAX_REL="<<rr<<" TERM_MAX_ABS="<<terms<<" TR_WA="<<std::abs(a.trace_wa-twa)<<" TR_WAWA="<<std::abs(a.trace_wawa-twawa)<<" R_WAWR="<<std::abs(a.quadratic_waw-qwaw)<<" TR_WAWAWQ="<<std::abs(a.trace_wawawq-twawawq)<<" SYMMETRIC_DD=PASS EXACT_REPEAT="<<(repeat?"PASS":"FAIL")<<" ACTIVE_H2D_BYTES="<<h1-h0<<" ACTIVE_D2H_BYTES="<<d1-d0<<" ZERO_REPEAT_H2D="<<(stationary?"PASS":"FAIL")<<'\n';return e<=1e-9&&rr<=1e-9&&terms<=1e-9&&repeat&&stationary;}
int main(){try{bool ok=run(3)&&run(100);std::cout<<"STREAMED_DELTA_HESSIAN_PARITY="<<(ok?"PASS":"FAIL")<<'\n';return ok?0:1;}catch(const std::exception&e){std::cerr<<e.what()<<'\n';return 2;}}
